/**
 * The Kitchen Codex — Advanced Nutrition Phase 1: canonical ingredient parsing
 * corpus.
 *
 * A bounded, deterministic corpus for the Phase 1 parsing slice: exact/range
 * quantities, household count nouns (leading and after the food), container
 * units, explicit package net masses, and preservation controls. Each entry
 * carries the canonical parse this slice must produce (offline, no USDA bundle)
 * and, where relevant, identity-safety expectations measured against the REAL
 * pinned bundle by `advancedNutritionPhase1ParsingCorpus.test.ts`.
 *
 * The corpus is additive: it neither replaces nor weakens the Phase 0A identity
 * corpus (`advancedNutritionIdentityCorpus.ts`), whose known-issue semantics
 * remain untouched.
 *
 * `knownIssue` marks a line whose identity/mass remains unresolved by design of
 * this slice; it only forbids an unsafe automatic bind, it does not bless the
 * current state.
 */

export interface Phase1PackageMassExpectation {
  readonly amount: number;
  readonly unit: 'g' | 'kg' | 'oz' | 'lb';
  /** `per_container` when grammar is deterministic; null when undetermined. */
  readonly scope: 'per_container' | 'total' | null;
}

export interface Phase1ParsingCase {
  readonly line: string;
  readonly category: string;
  /** Expected canonical quantity kind. */
  readonly quantityKind: 'exact' | 'range' | 'absent' | 'invalid';
  /** Expected exact amount (exact quantities only). */
  readonly amount?: number;
  readonly lower?: number;
  readonly upper?: number;
  /** Expected canonical unit (mass/volume id, count/container noun) or null. */
  readonly unit?: string | null;
  readonly unitKind?: 'mass' | 'volume' | 'count' | 'container' | 'unknown';
  readonly countNoun?: string | null;
  readonly container?: string | null;
  readonly packageMass?: Phase1PackageMassExpectation | null;
  /** The food phrase remaining after amount extraction. */
  readonly foodText: string;
  /** Identity-safety expectations (bundle-backed; see the corpus test). */
  readonly expectNoAutomatic?: boolean;
  /** The pipeline-selected automatic identity, when this slice fixes/keeps one. */
  readonly expectedAutoFdc?: number;
  readonly forbiddenAutoDescription?: RegExp;
  readonly expectCandidateDescription?: RegExp;
  /** Expected live grams, when an authenticated route resolves mass. */
  readonly expectLiveGrams?: number;
  /** Expected live mass source, when `expectLiveGrams` is set. */
  readonly expectMassSource?: string;
  /** Expected live status when mass must remain unresolved. */
  readonly expectLiveStatus?: string;
  readonly knownIssue?: string;
}

